  (N'd2ec01ca-2329-42a2-96b1-993c0883cdd7', NULL, NULL, N'Events', N'events', N'/events', N'default', N'Upcoming and recent events at our campuses.', N'published', N'2026-10-14T07:50:34.764156+00:00', 15, N'05a1bab5-f4ec-4b20-b8db-f49384795294', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL, NULL),
