  (N'056c738d-113f-407a-a129-3a3764e3049a', N'78527411-c33c-4c71-9cec-27ce29a233bb', N'values', N'{"body":"Three values guide every campus in our network.","items":[{"icon":"book-open","title":"Quality Education","description":"Teaching that builds real understanding, strong skills and good study habits."},{"icon":"moon-star","title":"Islamic Values","description":"Faith, worship and good conduct as part of everyday school life."},{"icon":"shield-check","title":"Strong Character","description":"Honesty, respect, discipline and responsibility in everything we do."}],"heading":"What we stand for"}', NULL, 2, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'0b577f09-fa7a-4bc1-befc-e952e0aa2fcb', N'66e16a59-5658-4616-8416-025be68f4ded', N'card_grid', N'{"items":[{"href":"/admissions","title":"Admissions","summary":"How to apply and what to expect."},{"href":"/downloads","title":"Downloads","summary":"Forms, notices and documents."},{"href":"/faq","title":"Frequently asked questions","summary":"Answers to common questions from parents."},{"href":"/branches","title":"Find a branch","summary":"Contact details and directions for each campus."}],"heading":"Useful links"}', NULL, 3, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'16b62736-d467-4a41-bd97-a4e5ebe0581b', N'364ae75b-16fc-4c1e-8c84-efda33c6df2a', N'cta_band', N'{"body":"Read the latest news, see upcoming events and browse photo albums.","tone":"warm","heading":"See what''s happening at our campuses","primary_cta":{"href":"/news","label":"News"},"secondary_cta":{"href":"/gallery","label":"Gallery"}}', NULL, 2, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'17852c00-6e29-489e-ae5a-450bede18278', N'91cedb2e-9452-4a34-b4f7-efcb9489b56e', N'split_feature', N'{"body":["Secondary students prepare for their Matric examinations with focused teaching, regular practice and guidance on study skills.","We also help students think about their next steps after Matric and the kind of people they want to become."],"image":{"alt":"Two secondary students studying together with their textbooks","path":"network/content/level-secondary--20261014075037.jpg","width":1183,"bucket":"public-media","height":887},"eyebrow":"Matric","heading":"Preparing for Matric and beyond","image_side":"left"}', NULL, 4, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:37.621935+00:00', NULL, NULL),
  (N'25393bb5-ba9a-46c6-b3ae-0f76244f30a0', N'1214144d-ebcf-464d-acc8-67d0d59600c5', N'card_grid', N'{"items":[{"title":"Understanding, not only memory","summary":"Children are encouraged to ask questions, explain their thinking and apply what they learn."},{"title":"Faith in daily life","summary":"Islamic teaching is part of the school day, not a separate subject that ends at the classroom door."},{"title":"Discipline with care","summary":"Clear routines and fair rules help children feel secure and focus on learning."},{"title":"Every child matters","summary":"Teachers pay attention to each child''s progress and wellbeing, and share concerns with parents early."},{"title":"Confidence through practice","summary":"Speaking, presenting, reading aloud and teamwork help children grow in confidence."},{"title":"Ready for the future","summary":"Good study habits, communication and responsibility prepare children for the next stage of life."}],"heading":"What this means in practice"}', NULL, 2, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'25a81629-8985-4506-9c43-9800479de555', N'8788c572-0b6c-4ac7-94cb-60643585d4fe', N'rich_text', N'{"body":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"We look for partners who share our commitment to quality education, Islamic values and good character.","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A suitable building in the proposed area, owned or rented","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A genuine commitment to education and to the local community","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Commitment to The Arqam Schools'' vision, values and quality standards","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Willingness to follow The Arqam Schools curriculum, training and policies","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Detailed requirements, including building size and investment, are shared by our franchise team during the evaluation meeting.","type":"text"}]}]},"anchor":"requirements","layout":"card","heading":"Franchise Requirements"}', NULL, 4, 1, N'2026-10-15T04:14:21.005197+00:00', N'2026-10-15T04:14:21.005197+00:00', NULL, NULL),
  (N'2ad9d360-ac8e-4cdf-ab93-4c2f1c62d800', N'abfa9c97-eb66-4746-a211-52472d85b3a9', N'process_steps', N'{"intro":"Every campus of The Arqam Schools works to:","steps":[{"title":"Teach well","description":"Provide quality modern education that builds understanding, skills and good study habits."},{"title":"Nurture faith","description":"Teach the Holy Quran and Islamic studies, and encourage worship and good conduct."},{"title":"Build character","description":"Develop discipline, good manners, honesty and responsibility in every child."},{"title":"Grow confidence","description":"Give children chances to speak, create, take part and lead."},{"title":"Work with parents","description":"Keep a close partnership between home and school for every child''s progress."}],"heading":"Our mission"}', NULL, 2, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'2cd6eabc-455b-4620-a9dc-2215e900fc08', N'91cedb2e-9452-4a34-b4f7-efcb9489b56e', N'split_feature', N'{"body":["In the early years, children settle into school life through play, stories, rhymes and simple routines. They begin to recognise letters and numbers, listen and speak with confidence, and learn their first duas and short surahs.","Above all, we want young children to feel safe and to enjoy learning."],"image":{"alt":"Young children building with colourful blocks in an early years classroom","path":"network/content/level-early-years--20261014075037.jpg","width":1365,"bucket":"public-media","height":1024},"eyebrow":"Early Years","heading":"A happy, caring start","image_side":"right"}', NULL, 1, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:37.506637+00:00', NULL, NULL),
  (N'31f0ebea-0df3-4d28-8d2d-a5c57d71f92c', N'5b38b611-53c9-432f-a1ae-a281bd12a25f', N'card_grid', N'{"intro":"Classes run from Play Group to Matric, with Hifz classes for students memorising the Holy Quran.","items":[{"href":"/academics/levels","meta":"From Play Group","image":{"alt":"Young children building with colourful blocks in an early years classroom","path":"network/content/level-early-years--20261014075037.jpg","width":1365,"bucket":"public-media","height":1024},"title":"Early Years","summary":"Learning through play, routine and stories."},{"href":"/academics/levels","meta":"Primary classes","image":{"alt":"Primary pupils at their desks, a girl raising her hand to answer","path":"network/content/level-primary--20261014075037.jpg","width":1255,"bucket":"public-media","height":941},"title":"Primary","summary":"Strong foundations in core subjects."},{"href":"/academics/levels","meta":"Middle classes","image":{"alt":"Students using a microscope and test tubes in a science lesson with their teacher","path":"network/content/level-middle--20261014075037.jpg","width":1365,"bucket":"public-media","height":1024},"title":"Middle","summary":"Deeper knowledge and independence."},{"href":"/academics/levels","meta":"Secondary classes","image":{"alt":"Two secondary students studying together with their textbooks","path":"network/content/level-secondary--20261014075037.jpg","width":1183,"bucket":"public-media","height":887},"title":"Matric","summary":"Focused examination preparation."},{"href":"/academics/levels","meta":"Hifz classes","image":{"alt":"A boy in a Hifz class reciting from the Holy Quran on a rehal as his teacher guides him","path":"network/content/hifz-quran-class--20261014075037.jpg","width":1183,"bucket":"public-media","height":887},"title":"Hifz-e-Quran","summary":"Memorising the Holy Quran with care."},{"href":"/about/values","meta":"At every level","image":{"alt":"A teacher guiding girls and boys as they read the Holy Quran on wooden stands","path":"network/content/islamic-studies--20261014075037.jpg","width":1365,"bucket":"public-media","height":1024},"title":"Islamic education","summary":"Quran, Islamic studies and good conduct."}],"heading":"Academic levels"}', NULL, 2, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:37.717688+00:00', NULL, NULL),
  (N'340b4694-f0cb-46bd-8afc-fab54e360fd0', N'265876a5-da95-4f76-b7dd-724710fb45e8', N'faq', N'{"items":[{"answer":"Our classes run from Play Group to Matric. We also offer Hifz classes for students memorising the Holy Quran. Classes can vary by campus, so please check with the campus you are interested in.","question":"Which classes does The Arqam Schools offer?"},{"answer":"Find your nearest campus on the Find a branch page, then contact the campus or send an admission inquiry through this website. The admissions team will explain the available classes, the documents needed and the next steps.","question":"How do I apply for admission?"},{"answer":"Fees depend on the campus and the class. Please contact the campus directly for the current fee structure.","question":"What are the fees?"},{"answer":"Admission arrangements depend on the class and the campus. The campus will tell you whether an assessment or meeting is part of the process for your child.","question":"Is there an admission test or interview?"},{"answer":"The campus will give you the list of documents for admission. Please contact the campus before your visit so that you can bring everything you need.","question":"What documents will I need?"},{"answer":"Yes. The Arqam Schools offers Hifz classes, and more than 15,000 students are currently learning in them. Please ask your campus whether Hifz classes are available there.","question":"Do you offer Hifz classes?"},{"answer":"Islamic education is part of everyday school life. Students learn to read and recite the Holy Quran, study Islamic teachings suited to their age, and are encouraged to practise good manners and good character.","question":"How is Islamic education taught?"},{"answer":"Transport arrangements differ from campus to campus. Please ask the campus you are interested in.","question":"Is transport available?"},{"answer":"You can call 041-2660265 or 041-2406479, or send a WhatsApp message to 0339-2406479. Our address is Sanora Colony, Samanabad, Faisalabad. You can also use the form on the Contact us page.","question":"How can I contact the head office?"}],"heading":"Questions from parents"}', NULL, 1, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'3b9e728d-e7c7-4afb-83ba-b3a4f8e5d2c2', N'8788c572-0b6c-4ac7-94cb-60643585d4fe', N'process_steps', N'{"tone":"grey","intro":"Four steps from your first inquiry to opening your campus.","steps":[{"title":"Submit Interest","description":"Fill in the online application with your details and proposed location."},{"title":"Evaluation Meeting","description":"Our franchise team reviews your application and meets you to discuss the location and next steps."},{"title":"Agreement & Setup","description":"Once approved, the franchise agreement is signed and the campus is prepared."},{"title":"Training & Launch","description":"Your staff are trained and the campus prepares to welcome its first students."}],"heading":"How It Works"}', NULL, 3, 1, N'2026-10-15T04:14:21.005197+00:00', N'2026-10-15T04:14:21.005197+00:00', NULL, NULL),
  (N'3da00ae0-f35e-441e-859f-b70e7ce573c7', N'ee9358dd-c72b-4890-a547-2dae0510ac55', N'split_feature', N'{"body":["Students learn to read and recite the Holy Quran correctly, and study Islamic teachings suited to their age. Our Hifz classes offer students the opportunity to memorise the Holy Quran, guided by their teachers.","Islamic education is taught with care and understanding, so that children connect what they learn with how they live."],"link":{"href":"/academics/levels","label":"Academic levels and Hifz classes"},"image":{"alt":"A teacher guiding girls and boys as they read the Holy Quran on wooden stands","path":"network/content/islamic-studies--20261014075037.jpg","width":1365,"bucket":"public-media","height":1024},"eyebrow":"Islamic education","heading":"The Holy Quran and Islamic studies","image_side":"right"}', NULL, 2, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:37.702264+00:00', NULL, NULL),
  (N'40d3ec0e-9257-450e-aa9e-87804812b8dc', N'91cedb2e-9452-4a34-b4f7-efcb9489b56e', N'split_feature', N'{"body":["Our Hifz classes give students the opportunity to memorise the Holy Quran with correct recitation, guided by their teachers. More than 15,000 students are currently learning in our Hifz classes.","Ask your campus whether it offers Hifz classes, and how Hifz is arranged alongside other subjects."],"image":{"alt":"A boy in a Hifz class reciting from the Holy Quran on a rehal as his teacher guides him","path":"network/content/hifz-quran-class--20261014075037.jpg","width":1183,"bucket":"public-media","height":887},"eyebrow":"Hifz-e-Quran","heading":"Hifz classes","image_side":"right"}', NULL, 5, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:37.663591+00:00', NULL, NULL),
  (N'4cd10378-9f62-43ec-aa82-7bf38f677fcd', N'78527411-c33c-4c71-9cec-27ce29a233bb', N'cta_band', N'{"body":"Find a campus near you and arrange a visit.","tone":"warm","heading":"See The Arqam Schools for yourself","primary_cta":{"href":"/branches","label":"Find a branch"},"secondary_cta":{"href":"/contact","label":"Contact us"}}', NULL, 4, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'5bf04f82-4168-4f36-8b1c-351c9f73385a', N'abfa9c97-eb66-4746-a211-52472d85b3a9', N'values', N'{"body":"To raise a generation of young people who combine knowledge with values: confident, capable and caring Muslims who lead with good character and serve their families, their communities and Pakistan, and who succeed in this world and the Hereafter.","items":[{"icon":"book-open","title":"Knowledge","description":"Strong learning in every subject, from early reading to Matric."},{"icon":"moon-star","title":"Faith","description":"A living connection with the Holy Quran and Islamic teachings."},{"icon":"shield-check","title":"Character","description":"Honesty, discipline, respect and responsibility."},{"icon":"users","title":"Leadership","description":"The confidence to speak, decide and serve others."}],"quote":{"text":"The basic aim and idea of The Arqam Schools is to earn the pleasure of Allah through the acts of education.","source":"The Arqam Schools"},"heading":"Our vision"}', NULL, 1, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'6c596445-42e1-45b6-b0b7-742ae363b024', N'66e16a59-5658-4616-8416-025be68f4ded', N'split_feature', N'{"body":["Children do best when parents and teachers work as partners. We encourage parents to stay in touch with their child''s campus, take an interest in schoolwork and share any concerns early.","Your child''s campus is your first point of contact for day-to-day matters such as timings, uniform, homework, assessments and fees."],"image":{"alt":"Placeholder image: a photo of parents meeting a teacher will appear here","path":"network/content/parents-and-teachers.jpg","width":1600,"bucket":"public-media","height":1200},"eyebrow":"For parents","heading":"Parents and school, working together","image_side":"right"}', NULL, 1, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'70873cc5-332b-4369-b3c9-ab5495943d6e', N'0f0f6041-712b-4fca-8b74-bc5a6066fa35', N'process_steps', N'{"intro":"Good teaching follows a simple rhythm that children come to know and trust.","steps":[{"title":"Explain clearly","description":"Teachers introduce new ideas step by step, with examples children can relate to."},{"title":"Learn actively","description":"Children discuss, ask questions, work in pairs and groups, and try things for themselves."},{"title":"Practise regularly","description":"Classwork and homework help children remember and use what they have learned."},{"title":"Check understanding","description":"Teachers check progress through questions, class tasks and assessments."},{"title":"Give feedback","description":"Children learn what they did well and how to improve; parents are kept informed."}],"heading":"How lessons help children learn"}', NULL, 1, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'735953ac-48d7-4f0b-bc23-5221abb64f10', N'bdf56766-64aa-4f0a-be27-8e62b642dfa1', N'split_feature', N'{"body":["At The Arqam Schools, your child receives a modern education rooted in Islamic values, in a disciplined and caring environment. From Play Group to Matric, and in our Hifz classes, we help children build knowledge, character and confidence."],"link":{"href":"/about/why-choose-us","label":"Why choose us"},"image":{"alt":"A teacher reading with a smiling student in the classroom","path":"network/content/admissions-banner--20261014075037.jpg","width":722,"bucket":"public-media","height":406},"eyebrow":"Why The Arqam Schools","heading":"Where knowledge meets values","image_side":"right"}', NULL, 2, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:37.873046+00:00', NULL, NULL),
  (N'749951e0-3e27-48a9-95d8-e1c42b17748a', N'5b38b611-53c9-432f-a1ae-a281bd12a25f', N'split_feature', N'{"body":["Our academic programme aims to give every child strong foundations and the confidence to build on them. Children develop reading, writing, mathematics and science skills step by step, and learn to think, question and explain.","Teachers plan lessons carefully, check understanding regularly and give children time to practise. Parents are kept informed about their child''s progress, so that support at home matches learning at school."],"link":{"href":"/academics/teaching","label":"Teaching methodology"},"image":{"alt":"Two primary students reading together at a desk with their schoolbooks","path":"network/content/students-reading-together--20261014075037.jpg","width":585,"bucket":"public-media","height":439},"eyebrow":"Academics","heading":"High expectations, steady progress","image_side":"right"}', NULL, 1, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:37.934245+00:00', NULL, NULL),
  (N'7e9bff44-0d37-4808-b4a4-4c0a8b62cafc', N'5b38b611-53c9-432f-a1ae-a281bd12a25f', N'card_grid', N'{"items":[{"image":{"alt":"A girl reading a picture book in the library","path":"network/content/languages-girl-reading--20261014075037.jpg","width":424,"bucket":"public-media","height":318},"title":"Languages","summary":"Reading, writing, speaking and listening, building confident communicators."},{"image":{"alt":"A boy building a molecule model in a science lesson","path":"network/content/science-molecule-model--20261014075037.jpg","width":424,"bucket":"public-media","height":318},"title":"Mathematics and science","summary":"Problem solving, reasoning and curiosity about the world."},{"image":{"alt":"A girl working on a laptop in a computer lesson","path":"network/content/computer-learning--20261014075037.jpg","width":424,"bucket":"public-media","height":318},"title":"Computer learning","summary":"Using technology sensibly and safely to learn and create."},{"image":{"alt":"A boy in a prayer cap reading the Holy Quran","path":"network/content/boy-reading-quran--20261014075037.jpg","width":424,"bucket":"public-media","height":318},"title":"Islamic education","summary":"The Holy Quran, Islamic studies and good conduct."}],"heading":"Learning across the curriculum"}', NULL, 3, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:37.98968+00:00', NULL, NULL),
  (N'7fc6be99-f210-46b2-81f3-535726c9b275', N'ee9358dd-c72b-4890-a547-2dae0510ac55', N'values', N'{"body":"Islamic values are at the heart of our schools. They shape how children speak, how they treat others, how they work and how they carry themselves, at school and at home.","items":[{"icon":"moon-star","title":"Faith and worship","description":"Learning the Holy Quran, duas and the basics of worship, with respect and love."},{"icon":"shield-check","title":"Honesty","description":"Telling the truth, keeping promises and doing one''s own work."},{"icon":"users","title":"Respect","description":"Respect for parents, teachers, classmates and everyone around us."},{"icon":"heart-handshake","title":"Good manners","description":"Greeting with salaam, speaking kindly and behaving with dignity."},{"icon":"compass","title":"Discipline","description":"Punctuality, neatness, self-control and good routines."},{"icon":"sparkles","title":"Service","description":"Helping others and caring for the school and the community."}],"quote":{"text":"The basic aim and idea of The Arqam Schools is to earn the pleasure of Allah through the acts of education.","source":"The Arqam Schools"},"heading":"Character is the first lesson"}', NULL, 1, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'9cbdcc31-fa2d-484a-85f9-54867496a817', N'91cedb2e-9452-4a34-b4f7-efcb9489b56e', N'cta_band', N'{"body":"Classes and availability vary by campus. Contact the campus to ask about a particular class.","tone":"warm","heading":"Which classes does your nearest campus offer?","primary_cta":{"href":"/branches","label":"Find a branch"},"secondary_cta":{"href":"/contact?type=admissions","label":"Send an inquiry"}}', NULL, 6, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'9ef048f1-7d85-4973-8275-b9e2bda74b05', N'bdf56766-64aa-4f0a-be27-8e62b642dfa1', N'process_steps', N'{"intro":"Admission is arranged by each campus. These are the usual steps.","steps":[{"title":"Find a campus","description":"Use Find a branch to choose a campus near your home."},{"title":"Get in touch","description":"Call the campus or send an admission inquiry through this website."},{"title":"Visit and discuss","description":"Visit the campus, meet the team and ask about classes, availability and fees."},{"title":"Complete admission","description":"The campus will explain the documents and steps needed to complete admission."}],"heading":"How admission works"}', NULL, 1, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'a22a8519-5fac-4b56-a119-23960455f0bc', N'91cedb2e-9452-4a34-b4f7-efcb9489b56e', N'split_feature', N'{"body":["Primary pupils build the core skills that everything else depends on: fluent reading, clear writing, confident arithmetic and an early understanding of science and the world around them.","Daily Islamic learning, good manners and classroom routines help children become responsible and independent learners."],"image":{"alt":"Primary pupils at their desks, a girl raising her hand to answer","path":"network/content/level-primary--20261014075037.jpg","width":1255,"bucket":"public-media","height":941},"eyebrow":"Primary","heading":"Strong foundations","image_side":"left"}', NULL, 2, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:37.536394+00:00', NULL, NULL),
  (N'c18aa51d-a0b5-4ce1-89e0-1e9beaeed2e5', N'78527411-c33c-4c71-9cec-27ce29a233bb', N'card_grid', N'{"items":[{"href":"/about/vision-mission","title":"Vision and mission","summary":"What we are working towards, and how."},{"href":"/about/philosophy","title":"Educational philosophy","summary":"The beliefs behind how we teach and care for children."},{"href":"/about/values","title":"Islamic values and character","summary":"How faith and good character are built every day."},{"href":"/about/why-choose-us","title":"Why choose us","summary":"What families can expect from The Arqam Schools."}],"heading":"Learn more about us"}', NULL, 3, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'c8a8d587-ac6d-498f-8d37-cda33c48de08', N'265876a5-da95-4f76-b7dd-724710fb45e8', N'cta_band', N'{"body":"Send us a message and our team will reply.","tone":"warm","heading":"Didn''t find your answer?","primary_cta":{"href":"/contact","label":"Contact us"},"secondary_cta":{"href":"/branches","label":"Find a branch"}}', NULL, 2, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'ca84bca2-dfe9-4ec7-acbd-85baf86462db', N'253371af-eab9-40c2-8aab-8f281e69d871', N'card_grid', N'{"items":[{"title":"Knowledge with values","summary":"Modern academic education and Islamic education, taught together as one balanced education."},{"title":"Development of the whole child","summary":"Character, discipline, confidence and creativity matter to us as much as marks."},{"title":"Play Group to Matric","summary":"One school family for your child''s entire school journey."},{"title":"Hifz classes","summary":"More than 15,000 students are learning the Holy Quran by heart with us."},{"title":"300+ branches","summary":"A trusted network serving more than 200,000 students across Pakistan."},{"title":"A partnership with parents","summary":"Regular communication and shared expectations between home and school."}],"heading":"What makes The Arqam Schools different"}', NULL, 1, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'd4e4a2fc-38e8-499d-be6a-dc71967a3e0b', N'253371af-eab9-40c2-8aab-8f281e69d871', N'cta_band', N'{"body":"Search for an Arqam school near you, then contact the campus or visit.","tone":"navy","heading":"Find the right campus for your child","primary_cta":{"href":"/branches","label":"Find a branch"},"secondary_cta":{"href":"/admissions","label":"Admissions"}}', NULL, 2, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'dafb993b-613e-414b-85f3-1067df7c6c71', N'9128ce07-4639-4f3b-a5c5-840e2c3786cd', N'rich_text', N'{"body":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"This notice explains how the website of The Arqam Schools uses the information you send us. [To be reviewed and approved by the school before publishing.]","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"What we collect","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Contact and admission inquiries: your name, phone number, email address (if given), the campus and your message.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Online admission applications: the details you enter about the student and parent or guardian, and any documents you upload.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Job applications: your details, your CV and the vacancy you apply for.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"How we use it","type":"text"}]},{"type":"paragraph","content":[{"text":"We use this information only to reply to you, to process admission or job applications, and to run our schools. We do not sell it, and we do not use it for advertising.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Who can see it","type":"text"}]},{"type":"paragraph","content":[{"text":"Only staff who need it for their work can see it, for example the admissions team of the campus you chose. Documents are stored privately and are not public on the website.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"How long we keep it","type":"text"}]},{"type":"paragraph","content":[{"text":"[Retention periods to be decided by the school.] When information is no longer needed, it is deleted or anonymised.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Your choices","type":"text"}]},{"type":"paragraph","content":[{"text":"To ask about, correct or remove your information, contact us on 041-2660265 or 041-2406479, or write to us at Sanora Colony, Samanabad, Faisalabad.","type":"text"}]}]},"heading":null}', NULL, 1, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'dd41ea84-0f0c-46fb-ab65-49e5fe00d6ef', N'1214144d-ebcf-464d-acc8-67d0d59600c5', N'split_feature', N'{"body":["We believe education is more than passing examinations. A child''s education should develop their mind, their faith and their character together. That is why our schools bring knowledge, character, discipline, confidence and Islamic values into one balanced journey.","Children learn best when they feel safe, respected and encouraged. Our classrooms aim to be calm, orderly and warm, where children are expected to work hard, behave well and help each other.","We see parents as our partners. When home and school share the same expectations and values, children make steady progress in their learning and in their conduct."],"image":{"alt":"A teacher patiently guiding a young student during a Quran lesson","path":"network/content/teacher-with-students--20261014075037.jpg","width":1183,"bucket":"public-media","height":887},"eyebrow":"Educational philosophy","heading":"Educating the whole child","image_side":"left"}', NULL, 1, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:37.742899+00:00', NULL, NULL),
  (N'e2cfdb29-c6cc-4b5f-8365-d7ebe294ca9e', N'8788c572-0b6c-4ac7-94cb-60643585d4fe', N'page_header', N'{"image":{"alt":"A teacher patiently guiding a young student during a Quran lesson","path":"network/content/teacher-with-students--20261014075037.jpg","width":1183,"bucket":"public-media","height":887},"intro":"Join The Arqam Schools network and become part of our mission to provide quality education, Islamic values, and strong character development to the next generation.","title":"Partner With The Arqam Schools","eyebrow":"Franchise","primary_cta":{"href":"/franchise/apply","label":"Apply for Franchise"},"secondary_cta":{"href":"/franchise#benefits","label":"Explore Franchise Benefits"}}', NULL, 1, 1, N'2026-10-15T04:14:21.005197+00:00', N'2026-10-15T04:14:40.732747+00:00', NULL, NULL),
  (N'e5334068-e24a-4677-b702-3fcf68a4c5ef', N'91cedb2e-9452-4a34-b4f7-efcb9489b56e', N'split_feature', N'{"body":["In the middle years, students study each subject in more depth. They learn to organise their work, revise effectively and explain their reasoning.","They also take on more responsibility in class and in school activities, and grow in confidence."],"image":{"alt":"Students using a microscope and test tubes in a science lesson with their teacher","path":"network/content/level-middle--20261014075037.jpg","width":1365,"bucket":"public-media","height":1024},"eyebrow":"Middle","heading":"Deeper learning, growing independence","image_side":"right"}', NULL, 3, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:37.585869+00:00', NULL, NULL),
  (N'ef431471-83b3-4885-b54d-715f0dd993ff', N'364ae75b-16fc-4c1e-8c84-efda33c6df2a', N'card_grid', N'{"intro":"Activities give children room to discover their talents, work as a team and grow in confidence. The programme varies from campus to campus.","items":[{"image":{"alt":"A boy reading a picture book in front of a bookshelf","path":"network/content/library-reading--20261014075037.jpg","width":427,"bucket":"public-media","height":320},"title":"Reading","summary":"Encouraging a love of books and reading for pleasure."},{"image":{"alt":"Children painting pictures outdoors on the school lawn with their teacher","path":"network/content/creative-projects--20261014075037.jpg","width":1365,"bucket":"public-media","height":1024},"title":"Creative projects","summary":"Art, crafts and group projects that build imagination and teamwork."},{"image":{"alt":"Placeholder image: a photo of students taking part in sports will appear here","path":"network/content/sports-activities.jpg","width":1600,"bucket":"public-media","height":1200},"title":"Sports","summary":"Physical activity that builds health, discipline and fair play."},{"image":{"alt":"A girl working on a laptop in a computer lesson","path":"network/content/computer-learning--20261014075037.jpg","width":424,"bucket":"public-media","height":318},"title":"Science and technology","summary":"Exploring, experimenting and learning with computers."},{"image":{"alt":"A teacher guiding girls and boys as they read the Holy Quran on wooden stands","path":"network/content/islamic-studies--20261014075037.jpg","width":1365,"bucket":"public-media","height":1024},"title":"Islamic occasions","summary":"Marking important occasions in the Islamic calendar together."},{"image":{"alt":"A teacher patiently guiding a young student during a Quran lesson","path":"network/content/teacher-with-students--20261014075037.jpg","width":1183,"bucket":"public-media","height":887},"title":"Speaking and presenting","summary":"Recitation, speeches and presentations that build confidence."}],"heading":"Learning beyond the classroom"}', NULL, 1, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:37.84239+00:00', NULL, NULL),
  (N'f057c8d2-0311-4a7f-a63a-db6f4c38fd23', N'0f0f6041-712b-4fca-8b74-bc5a6066fa35', N'card_grid', N'{"items":[{"image":{"alt":"A girl writing carefully in her exercise book in class","path":"network/content/girl-writing-in-class--20261014075037.jpg","width":427,"bucket":"public-media","height":320},"title":"Calm and orderly","summary":"Clear routines and expectations help every child concentrate."},{"image":{"alt":"A boy reading a picture book in front of a bookshelf","path":"network/content/library-reading--20261014075037.jpg","width":427,"bucket":"public-media","height":320},"title":"Reading every day","summary":"Reading for learning and for enjoyment builds language and knowledge."},{"image":{"alt":"Two children building a toy car together in a hands-on activity","path":"network/content/hands-on-building-activity--20261014075037.jpg","width":427,"bucket":"public-media","height":320},"title":"Hands-on learning","summary":"Activities, projects and demonstrations bring lessons to life."},{"image":{"alt":"A smiling boy giving a thumbs up in front of a classroom values board","path":"network/content/boy-thumbs-up-values--20261014075037.jpg","width":427,"bucket":"public-media","height":320},"title":"Values in every lesson","summary":"Teachers model honesty, respect and good manners as they teach."}],"heading":"In our classrooms"}', NULL, 2, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:38.049553+00:00', NULL, NULL),
  (N'f64096b7-b893-40a8-a670-03d4ba67234b', N'bdf56766-64aa-4f0a-be27-8e62b642dfa1', N'faq', N'{"items":[{"answer":"Find your nearest campus on the Find a branch page, then contact the campus or send an admission inquiry through this website. The admissions team will explain the available classes, the documents needed and the next steps.","question":"How do I apply for admission?"},{"answer":"Fees depend on the campus and the class. Please contact the campus directly for the current fee structure.","question":"What are the fees?"},{"answer":"Admission arrangements depend on the class and the campus. The campus will tell you whether an assessment or meeting is part of the process for your child.","question":"Is there an admission test or interview?"},{"answer":"The campus will give you the list of documents for admission. Please contact the campus before your visit so that you can bring everything you need.","question":"What documents will I need?"}],"heading":"Admission questions"}', NULL, 3, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'f75bd919-32e7-464d-b71e-6ca6a8ec610c', N'78527411-c33c-4c71-9cec-27ce29a233bb', N'split_feature', N'{"body":["The Arqam Schools is an educational network in Pakistan with more than 300 branches and over 200,000 students. Our classes run from Play Group to Matric, and our Hifz classes are helping more than 15,000 students learn the Holy Quran by heart.","We believe a good education develops the whole child. Alongside strong academic teaching, our students learn Islamic values, good manners and self-discipline, so they grow into confident, knowledgeable and responsible people.","The basic aim and idea of The Arqam Schools is to earn the pleasure of Allah through the acts of education."],"image":{"alt":"Students of different ages walking together outside a school building","path":"network/content/about-campus--20261014075037.jpg","width":800,"bucket":"public-media","height":600},"eyebrow":"Who we are","heading":"One network, one purpose","image_side":"right"}', NULL, 1, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:37.469604+00:00', NULL, NULL),
  (N'f9005cd7-8221-4349-be4e-68d827d8b06c', N'66e16a59-5658-4616-8416-025be68f4ded', N'card_grid', N'{"items":[{"title":"Keep a routine","summary":"Regular sleep, a good breakfast and arriving on time help children learn."},{"title":"Read together","summary":"A few minutes of reading every day makes a lasting difference."},{"title":"Check homework","summary":"Ask your child about their day and look at their homework diary."},{"title":"Encourage good manners","summary":"Praise honesty, kindness and respect at home as we do at school."},{"title":"Stay in touch","summary":"Attend meetings at your campus and read notices sent home."},{"title":"Talk to us early","summary":"If something worries you, contact your child''s teacher or campus."}],"heading":"How you can help at home"}', NULL, 2, 1, N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'f95f365d-f37d-421b-a394-496338bee9f9', N'8788c572-0b6c-4ac7-94cb-60643585d4fe', N'cta_band', N'{"body":"Submit your interest online. Our franchise team will review it and contact you.","tone":"navy","heading":"Ready to partner with us?","primary_cta":{"href":"/franchise/apply","label":"Apply for Franchise"},"secondary_cta":{"href":"/contact","label":"Contact the head office"}}', NULL, 5, 1, N'2026-10-15T04:14:21.005197+00:00', N'2026-10-15T04:14:21.005197+00:00', NULL, NULL),
  (N'fa703b48-2ccd-4263-b65f-90ed403fda74', N'8788c572-0b6c-4ac7-94cb-60643585d4fe', N'values', N'{"body":"What partnering with The Arqam Schools offers you and the families in your community.","items":[{"icon":"book-open","title":"Proven Curriculum","description":"A structured programme from Play Group to Matric that combines modern subjects with Islamic education."},{"icon":"graduation-cap","title":"Teacher Training","description":"Training for your teachers so lessons follow The Arqam Schools approach to learning and character."},{"icon":"award","title":"Brand Recognition","description":"Open under a name that families know, as part of a network of 300+ branches across Pakistan."},{"icon":"shield-check","title":"Quality Assurance","description":"Shared standards and regular reviews help every campus deliver the quality parents expect."},{"icon":"headset","title":"Ongoing Support","description":"Guidance from our team on academics, operations and admissions as your campus grows."},{"icon":"wallet","title":"Affordable Investment","description":"Investment requirements are explained clearly at the start, so you can plan with confidence."}],"anchor":"benefits","layout":"cards","heading":"Why Franchise With Us?"}', NULL, 2, 1, N'2026-10-15T04:14:21.005197+00:00', N'2026-10-15T04:14:21.005197+00:00', NULL, NULL);
