  (N'0602015a-60c6-4a76-902d-fc82209d7b19', N'quick_actions', N'quick_actions', N'{"stats":[{"label":"Branches across Pakistan","value":"300+"},{"label":"Students","value":"200,000+"},{"label":"Hifz-e-Quran students","value":"15,000+"}],"actions":[{"href":"/branches","icon":"map-pin","label":"Find a branch"},{"href":"/admissions","icon":"clipboard-check","label":"Admissions"},{"href":"/parents","icon":"users","label":"Parent information"},{"href":"/contact","icon":"phone","label":"Contact us"}]}', NULL, 2, 1, 0, N'published', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'09162c2d-4386-467d-a1a9-07ee26198fe5', N'academics', N'card_grid', N'{"intro":"Each stage builds on the last, with strong foundations in language, mathematics and science, alongside Islamic education and character building.","items":[{"href":"/academics/levels","meta":"From Play Group","image":{"alt":"Young children building with colourful blocks in an early years classroom","path":"network/content/level-early-years--20261014075037.jpg","width":1365,"bucket":"public-media","height":1024},"title":"Early Years","summary":"A caring start where young children learn through play, stories and routine, and begin to read, count and recite."},{"href":"/academics/levels","meta":"Primary classes","image":{"alt":"Primary pupils at their desks, a girl raising her hand to answer","path":"network/content/level-primary--20261014075037.jpg","width":1255,"bucket":"public-media","height":941},"title":"Primary","summary":"Strong foundations in reading, writing, mathematics and science, with daily Islamic learning and good manners."},{"href":"/academics/levels","meta":"Middle classes","image":{"alt":"Students using a microscope and test tubes in a science lesson with their teacher","path":"network/content/level-middle--20261014075037.jpg","width":1365,"bucket":"public-media","height":1024},"title":"Middle","summary":"Deeper subject knowledge, independent study habits and growing confidence in speaking and thinking."},{"href":"/academics/levels","meta":"Secondary classes","image":{"alt":"Two secondary students studying together with their textbooks","path":"network/content/level-secondary--20261014075037.jpg","width":1183,"bucket":"public-media","height":887},"title":"Matric","summary":"Focused preparation for the Matric examinations, with guidance on study skills and next steps."},{"href":"/academics/levels","meta":"Hifz classes","image":{"alt":"A boy in a Hifz class reciting from the Holy Quran on a rehal as his teacher guides him","path":"network/content/hifz-quran-class--20261014075037.jpg","width":1183,"bucket":"public-media","height":887},"title":"Hifz-e-Quran","summary":"Memorisation of the Holy Quran with correct recitation, guided by teachers, with care for the child''s wider education."},{"href":"/about/values","meta":"At every level","image":{"alt":"A teacher guiding girls and boys as they read the Holy Quran on wooden stands","path":"network/content/islamic-studies--20261014075037.jpg","width":1365,"bucket":"public-media","height":1024},"title":"Islamic education","summary":"The Holy Quran, Islamic studies and good conduct are part of every child''s school day."}],"eyebrow":"Academic programmes","heading":"A complete learning journey, from Play Group to Matric"}', NULL, 4, 1, 0, N'published', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:37.694867+00:00', NULL, NULL),
  (N'3df243f5-f8b9-4ed8-b39e-c3d090f3a099', N'careers_closing', N'careers_closing', N'{"careers_cta":{"href":"/careers","label":"View vacancies"},"closing_cta":{"href":"/admissions","label":"Admissions"},"careers_body":"We welcome teachers and staff who share our commitment to quality education and Islamic values.","closing_body":"Give your child an education that builds knowledge, character and confidence.","careers_heading":"Teach and grow with us","closing_heading":"Learn Today. Lead Tomorrow."}', NULL, 14, 1, 0, N'published', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'51da3de9-08f3-44cf-94ce-79a48374c474', N'student_life', N'split_feature', N'{"body":["Reading, creative projects, sports and special occasions give children room to explore their interests, work in teams and build confidence.","Activities vary from campus to campus. Your campus will share its programme for the year."],"link":{"href":"/student-life","label":"Student life and activities"},"image":{"alt":"Children painting pictures outdoors on the school lawn with their teacher","path":"network/content/creative-projects--20261014075037.jpg","width":1365,"bucket":"public-media","height":1024},"eyebrow":"Student life","heading":"Learning beyond the classroom","image_side":"left"}', NULL, 9, 1, 0, N'published', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:37.834748+00:00', NULL, NULL),
  (N'6a014c67-b53a-4535-83ac-f99c6c96b9be', N'why_choose', N'card_grid', N'{"items":[{"title":"Modern education rooted in Islamic values","summary":"Academic subjects and Islamic education are taught side by side, as one balanced education."},{"title":"The whole child","summary":"We care about knowledge, character, discipline and confidence, not only examination marks."},{"title":"From Play Group to Matric","summary":"Children can continue their education with us from their first school day to Matric."},{"title":"Hifz-e-Quran","summary":"More than 15,000 students are learning the Holy Quran by heart in our Hifz classes."},{"title":"A network you can trust","summary":"More than 300 branches across Pakistan share the same values and standards of care."},{"title":"Parents as partners","summary":"We keep parents informed and involved, because children do best when home and school work together."}],"eyebrow":"Why choose us","heading":"Why families choose The Arqam Schools"}', NULL, 6, 1, 0, N'published', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'8f1a378a-aa08-41f0-8f23-77c19398fcec', N'news_events', N'news_events', N'{"news_heading":"Latest news","events_heading":"Upcoming events"}', NULL, 10, 1, 0, N'published', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'980166c4-c5f5-4975-af89-f5849d43591c', N'testimonials', N'testimonials', N'{"heading":"What parents say"}', NULL, 13, 1, 0, N'published', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'a22dab15-7a0e-4bb7-b7e5-fe367cc53be8', N'about', N'split_feature', N'{"body":["The Arqam Schools is a network of more than 300 schools across Pakistan, where over 200,000 students learn every day. We bring together modern academic education and Islamic education, so that children grow in knowledge, faith and character at the same time.","From Play Group to Matric, and in our Hifz classes, we work in partnership with parents to raise confident, disciplined and responsible young people who are prepared for success in this world and the Hereafter."],"link":{"href":"/about","label":"About The Arqam Schools"},"image":{"alt":"Students of different ages walking together outside a school building","path":"network/content/about-campus--20261014075037.jpg","width":800,"bucket":"public-media","height":600},"eyebrow":"About us","heading":"Knowledge with values. Education with purpose.","image_side":"right"}', NULL, 3, 1, 0, N'published', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:37.460045+00:00', NULL, NULL),
  (N'ba16a244-5c37-4a76-b626-4fe701208c66', N'branch_finder', N'branch_finder', N'{"intro":"Search by city, area or campus name to find contact details and directions.","heading":"Find an Arqam school near you"}', NULL, 8, 1, 0, N'published', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'bafe3161-acdf-4533-b913-4dae3afd544d', N'achievements', N'achievements', N'{"intro":"Celebrating the hard work of our students.","heading":"Student achievements"}', NULL, 11, 1, 0, N'published', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'bc47671f-11c7-4a4d-9caf-ab5b0795ac1c', N'hero', N'hero', N'{"slides":[{"alt":"A girl raising her hand to answer in a bright primary classroom","path":"network/content/hero-students-classroom--20261014075037.jpg","width":1958,"bucket":"public-media","height":803},{"alt":"A girl in a hijab writing at her desk while her teacher looks on","path":"network/content/hero-slide-2--20261014075037.jpg","width":1959,"bucket":"public-media","height":803}],"eyebrow":"The Arqam Schools","headline":"Learn Today. Lead Tomorrow.","primary_cta":{"href":"/admissions","label":"Admissions"},"subheadline":"Quality Education | Islamic Values | Strong Character","mobile_image":{"alt":"A girl raising her hand to answer in a bright primary classroom","path":"network/content/hero-mobile--20261014075037.jpg","width":660,"bucket":"public-media","height":803},"secondary_cta":{"href":"/branches","label":"Find a branch"}}', NULL, 1, 1, 1, N'published', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:37.910894+00:00', NULL, NULL),
  (N'c33da0cd-0ad3-4cfd-9966-d42bf17cbef9', N'values', N'values', N'{"body":"Education at The Arqam Schools is not only about results. It is about developing the whole child: what they know, how they behave and who they become.","items":[{"icon":"book-open","title":"Quality Education","description":"Clear teaching, regular practice and attention to each child''s progress."},{"icon":"moon-star","title":"Islamic Values","description":"Quran, Islamic studies and daily practice that shape faith and conduct."},{"icon":"shield-check","title":"Strong Character","description":"Honesty, respect, kindness and responsibility, taught and modelled every day."},{"icon":"compass","title":"Discipline","description":"Good routines, punctuality and self-control that help children learn well."},{"icon":"star","title":"Confidence","description":"Chances to speak, present and lead, so children believe in their abilities."},{"icon":"heart-handshake","title":"Responsibility","description":"Caring for others, for their school and for their community."}],"quote":{"text":"The basic aim and idea of The Arqam Schools is to earn the pleasure of Allah through the acts of education.","source":"The Arqam Schools"},"heading":"Islamic values and strong character"}', NULL, 5, 1, 0, N'published', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
  (N'd2c7f9c7-6580-4818-b819-0cced79ec68f', N'admissions_cta', N'cta_band', N'{"body":"Visit your nearest campus or send an admission inquiry. Our team will guide you through classes, availability and the next steps.","tone":"navy","steps":["Find a branch","Send an inquiry","Visit the campus"],"heading":"Start your child''s learning journey with us","primary_cta":{"href":"/admissions","label":"Admissions"},"secondary_cta":{"href":"/contact?type=admissions","label":"Send an inquiry"},"heading_when_open":"Admissions are open"}', NULL, 7, 1, 0, N'published', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', N'2026-10-14T07:50:34.764156+00:00', NULL, NULL),
